import type {
  RuntimeExecutionRequest as HarborRuntimeExecutionRequest,
  RuntimeExecutionResult as HarborRuntimeExecutionResult,
} from '@hrbr/core/runtime'
import type {
  RuntimeExecutionMode,
  RuntimeExecutionRequest,
  RuntimeExecutionResult,
  RuntimeMetadata,
  TrustedExecutionContext,
} from '@hrbr/runtime-core'

const toRuntimeMode = (kind: HarborRuntimeExecutionRequest['kind']): RuntimeExecutionMode => {
  if (kind === 'workflow') return 'workflow'
  if (kind === 'tool_invocation') return 'exec'
  return 'exec'
}

export const harborRequestToRuntimeRequest = (
  request: HarborRuntimeExecutionRequest
): RuntimeExecutionRequest => ({
  code: typeof request.payload === 'string' ? request.payload : '',
  mode: toRuntimeMode(request.kind),
})

export const harborRequestToTrustedContext = (
  request: HarborRuntimeExecutionRequest
): TrustedExecutionContext => ({
  scopeId: request.workspace_id,
  runId: request.run_id ?? 'unassigned-run',
})

export const runtimeResultToHarborResult = (
  result: RuntimeExecutionResult,
  context: TrustedExecutionContext
): HarborRuntimeExecutionResult => ({
  ok: result.error === undefined,
  run_id: context.runId,
  output: result.result,
  error: result.error,
})

export interface HarborWorkerSourceRef {
  readonly namespace: string
}

export interface HarborWorkerExecutionInput {
  readonly path: string
  readonly content_type?: string | undefined
  readonly data_base64: string
  readonly sha256?: string | undefined
  readonly size_bytes?: number | undefined
}

export interface HarborWorkerExecutionRequest {
  readonly workspace_id: string
  readonly run_id?: string | undefined
  readonly code: string
  readonly timeout_ms?: number | undefined
  readonly sources?: ReadonlyArray<HarborWorkerSourceRef> | undefined
  readonly execution_inputs?: ReadonlyArray<HarborWorkerExecutionInput> | undefined
  readonly mode?: string | undefined
  readonly workflow_step?: unknown
  readonly agent_id?: string | undefined
  readonly sand_machine_id?: string | undefined
}

export interface HarborWorkerRuntimeOptions {
  readonly mode?: RuntimeExecutionMode | undefined
  readonly attributionId?: string | undefined
  readonly machineId?: string | undefined
  readonly trace?: RuntimeMetadata | undefined
  readonly features?: RuntimeMetadata | undefined
}

const toWorkerRuntimeMode = (
  request: HarborWorkerExecutionRequest,
  options?: HarborWorkerRuntimeOptions | undefined
): RuntimeExecutionMode => {
  if (options?.mode) return options.mode
  if (request.mode === 'workflow' || request.workflow_step) return 'workflow'
  return 'exec'
}

export const harborWorkerRequestToRuntimeRequest = (
  request: HarborWorkerExecutionRequest,
  options: HarborWorkerRuntimeOptions = {}
): RuntimeExecutionRequest => {
  const sourceFilter = request.sources?.map((source) => source.namespace)
  const executionInputs = request.execution_inputs?.map((input) => ({
    name: input.path,
    contentType: input.content_type,
    data: input.data_base64,
    sha256: input.sha256,
  }))

  return {
    code: request.code,
    mode: toWorkerRuntimeMode(request, options),
    ...(request.timeout_ms !== undefined ? { timeoutMs: request.timeout_ms } : {}),
    ...(executionInputs && executionInputs.length > 0 ? { executionInputs } : {}),
    ...(sourceFilter && sourceFilter.length > 0 ? { sourceFilter } : {}),
    ...(options.features ? { features: options.features } : {}),
  }
}

export const harborWorkerRequestToTrustedContext = (
  request: HarborWorkerExecutionRequest,
  options: HarborWorkerRuntimeOptions = {}
): TrustedExecutionContext => {
  const attributionId = options.attributionId ?? request.agent_id
  const machineId = options.machineId ?? request.sand_machine_id

  return {
    scopeId: request.workspace_id,
    runId: request.run_id ?? 'unassigned-run',
    ...(attributionId ? { attributionId } : {}),
    ...(machineId ? { machineId } : {}),
    ...(options.trace ? { trace: options.trace } : {}),
  }
}
